actions:
  set_default_payment_method:
    method: POST
    path: /customers/{id}/default_payment_method
    description: Make one of the customer's own active cards the default card charged for invoices.
    input:
      payment_method_id:
        type: ref
        description: A card that belongs to the customer and is active.
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: payment_method
        onDelete: restrict
    handler: "(ctx) => { const cus = ctx.db.get('customer', ctx.params.id); if (cus === null) ctx.fail(404, 'not_found', 'customer ' + ctx.params.id + ' not found'); const pm = ctx.db.get('payment_method', ctx.body.payment_method_id); if (pm === null) ctx.fail(400, 'input.invalid', 'payment_method ' + ctx.body.payment_method_id + ' not found'); if (pm.customer_id !== cus.id) ctx.fail(409, 'payment_method_mismatch', 'payment method ' + pm.id + ' does not belong to customer ' + cus.id + '. List cards with GET /customers/' + cus.id + '/payment_methods.'); if (!pm.active) ctx.fail(409, 'payment_method_inactive', 'payment method ' + pm.id + ' is inactive. Pick an active card.'); const updated = ctx.db.update('customer', cus.id, { default_payment_method_id: pm.id }); return { status: 200, body: updated }; }"
  subscribe:
    method: POST
    path: /subscriptions
    description: "Subscribe a customer to an active plan and charge the first invoice at once. Answers 201 even when the charge fails: the subscription is then past_due and dunning starts. An optional payment_method_id must belong to the customer and becomes their default card."
    input:
      customer_id:
        type: ref
        description: The customer who subscribes.
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: customer
        onDelete: restrict
      plan_id:
        type: ref
        description: An active plan.
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: plan
        onDelete: restrict
      payment_method_id:
        type: ref
        description: Optional card of the customer. It becomes the default and is charged.
        required: false
        nullable: true
        unique: false
        readonly: false
        entity: payment_method
        onDelete: restrict
    handler: "(ctx) => { const now = ctx.now(); const FAIL = { tok_chargeDeclined: 'card_declined', tok_insufficient_funds: 'insufficient_funds', tok_expired_card: 'expired_card' }; const cus = ctx.db.get('customer', ctx.body.customer_id); if (cus === null) ctx.fail(400, 'input.invalid', 'customer ' + ctx.body.customer_id + ' not found'); const plan = ctx.db.get('plan', ctx.body.plan_id); if (plan === null) ctx.fail(400, 'input.invalid', 'plan ' + ctx.body.plan_id + ' not found'); if (!plan.active) ctx.fail(409, 'plan_inactive', 'plan ' + plan.id + ' is inactive and takes no new subscriptions.'); if (ctx.db.list('subscription', { where: { customer_id: cus.id, plan_id: plan.id } }).some((s) => s.status !== 'canceled')) ctx.fail(409, 'duplicate_subscription', 'customer ' + cus.id + ' already has a subscription to plan ' + plan.id + '.'); let pm = null; if (ctx.body.payment_method_id) { pm = ctx.db.get('payment_method', ctx.body.payment_method_id); if (pm === null) ctx.fail(400, 'input.invalid', 'payment_method ' + ctx.body.payment_method_id + ' not found'); if (pm.customer_id !== cus.id) ctx.fail(409, 'payment_method_mismatch', 'payment method ' + pm.id + ' does not belong to customer ' + cus.id + '.'); if (!pm.active) ctx.fail(409, 'payment_method_inactive', 'payment method ' + pm.id + ' is inactive.'); } else if (cus.default_payment_method_id) { const d = ctx.db.get('payment_method', cus.default_payment_method_id); if (d !== null && d.active) pm = d; } if (pm === null) ctx.fail(409, 'no_payment_method', 'customer ' + cus.id + ' has no usable default payment method. Add a card and set it as default first.'); if (cus.default_payment_method_id !== pm.id) ctx.db.update('customer', cus.id, { default_payment_method_id: pm.id }); let seq = 0; for (const i of ctx.db.list('invoice')) { const n = parseInt(String(i.number).replace(/[^0-9]/g, ''), 10); if (n > seq) seq = n; } const end = ctx.time.plus(now, (plan.interval === 'year' ? 365 : 30) + 'd'); const sub = ctx.db.create('subscription', { customer_id: cus.id, plan_id: plan.id, current_period_start: now, current_period_end: end, canceled_at: null, cancel_reason: null }); const inv = ctx.db.create('invoice', { number: 'INV-' + String(seq + 1).padStart(4, '0'), subscription_id: sub.id, customer_id: cus.id, amount_due: plan.amount, period_start: now, period_end: end, attempt_count: 1, dunning_started_at: null, next_retry_at: null, last_failure_code: null, paid_at: null }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'created', note: 'subscribed to ' + plan.code + ', invoice ' + inv.number }); const code = FAIL[pm.token] === undefined ? null : FAIL[pm.token]; if (code === null) { ctx.db.create('payment', { invoice_id: inv.id, payment_method_id: pm.id, amount: plan.amount, status: 'succeeded', failure_code: null, kind: 'initial' }); ctx.db.update('invoice', inv.id, { status: 'paid', paid_at: now }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'payment_succeeded', note: 'first invoice paid with card ending ' + pm.last4 }); } else { const next = ctx.time.plus(now, '1d'); ctx.db.create('payment', { invoice_id: inv.id, payment_method_id: pm.id, amount: plan.amount, status: 'failed', failure_code: code, kind: 'initial' }); ctx.db.update('invoice', inv.id, { dunning_started_at: now, next_retry_at: next, last_failure_code: code }); ctx.db.update('subscription', sub.id, { status: 'past_due' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'payment_failed', note: 'first charge failed: ' + code }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'past_due', note: 'subscription is past due' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'retry_scheduled', note: 'next retry scheduled for ' + next }); } return { status: 201, body: ctx.db.get('subscription', sub.id) }; }"
  cancel_subscription:
    method: POST
    path: /subscriptions/{id}/cancel
    description: Cancel an active or past_due subscription now. Open invoices become void and retries stop. Paid invoices stay paid.
    input: {}
    handler: "(ctx) => { const id = ctx.params.id; const sub = ctx.db.get('subscription', id); if (sub === null) ctx.fail(404, 'not_found', 'subscription ' + id + ' not found'); if (sub.status !== 'active' && sub.status !== 'past_due') ctx.fail(409, 'invalid_state', 'subscription ' + id + ' is ' + sub.status + '. Only active and past_due subscriptions can be canceled.'); const now = ctx.now(); const updated = ctx.db.update('subscription', id, { status: 'canceled', canceled_at: now, cancel_reason: 'requested' }); for (const inv of ctx.db.list('invoice', { where: { subscription_id: id, status: 'open' } })) { ctx.db.update('invoice', inv.id, { status: 'void', next_retry_at: null }); } ctx.db.create('billing_event', { subscription_id: id, invoice_id: null, kind: 'canceled', note: 'canceled on request' }); return { status: 200, body: updated }; }"
  change_plan:
    method: POST
    path: /subscriptions/{id}/change_plan
    description: Switch the subscription to another active plan. Only plan_id changes. The new amount applies from the next renewal, with no proration.
    input:
      plan_id:
        type: ref
        description: The new, active plan.
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: plan
        onDelete: restrict
    handler: "(ctx) => { const id = ctx.params.id; const sub = ctx.db.get('subscription', id); if (sub === null) ctx.fail(404, 'not_found', 'subscription ' + id + ' not found'); if (sub.status === 'canceled') ctx.fail(409, 'invalid_state', 'subscription ' + id + ' is canceled and cannot change plan.'); const plan = ctx.db.get('plan', ctx.body.plan_id); if (plan === null) ctx.fail(400, 'input.invalid', 'plan ' + ctx.body.plan_id + ' not found'); if (plan.id === sub.plan_id) ctx.fail(409, 'no_change', 'subscription ' + id + ' is already on plan ' + plan.id + '.'); if (!plan.active) ctx.fail(409, 'plan_inactive', 'plan ' + plan.id + ' is inactive.'); const updated = ctx.db.update('subscription', id, { plan_id: plan.id }); ctx.db.create('billing_event', { subscription_id: id, invoice_id: null, kind: 'plan_changed', note: 'plan changed from ' + sub.plan_id + ' to ' + plan.id + ', effective from the next renewal' }); return { status: 200, body: updated }; }"
  pay_invoice:
    method: POST
    path: /invoices/{id}/pay
    description: Charge an open invoice now with the customer's default card or a named active card of the customer. A declined charge answers 200 with the failed payment and leaves the dunning schedule unchanged. A success pays the invoice and reactivates a past_due subscription.
    input:
      payment_method_id:
        type: ref
        description: Optional card of the invoice's customer. Defaults to the customer's default card.
        required: false
        nullable: true
        unique: false
        readonly: false
        entity: payment_method
        onDelete: restrict
    handler: "(ctx) => { const FAIL = { tok_chargeDeclined: 'card_declined', tok_insufficient_funds: 'insufficient_funds', tok_expired_card: 'expired_card' }; const id = ctx.params.id; const inv = ctx.db.get('invoice', id); if (inv === null) ctx.fail(404, 'not_found', 'invoice ' + id + ' not found'); if (inv.status !== 'open') ctx.fail(409, 'invoice_not_open', 'invoice ' + id + ' is ' + inv.status + '. Only open invoices can be paid.'); let pm = null; if (ctx.body.payment_method_id) { pm = ctx.db.get('payment_method', ctx.body.payment_method_id); if (pm === null) ctx.fail(400, 'input.invalid', 'payment_method ' + ctx.body.payment_method_id + ' not found'); if (pm.customer_id !== inv.customer_id || !pm.active) ctx.fail(409, 'payment_method_mismatch', 'payment method ' + pm.id + ' is not an active card of customer ' + inv.customer_id + '.'); } else { const cus = ctx.db.get('customer', inv.customer_id); if (cus.default_payment_method_id) { const d = ctx.db.get('payment_method', cus.default_payment_method_id); if (d !== null && d.active) pm = d; } if (pm === null) ctx.fail(409, 'no_payment_method', 'customer ' + inv.customer_id + ' has no usable default payment method.'); } const now = ctx.now(); const code = FAIL[pm.token] === undefined ? null : FAIL[pm.token]; const sub = ctx.db.get('subscription', inv.subscription_id); if (code !== null) { const failed = ctx.db.create('payment', { invoice_id: inv.id, payment_method_id: pm.id, amount: inv.amount_due, status: 'failed', failure_code: code, kind: 'manual' }); ctx.db.create('billing_event', { subscription_id: inv.subscription_id, invoice_id: inv.id, kind: 'payment_failed', note: 'manual payment failed: ' + code }); return { status: 200, body: failed }; } const paid = ctx.db.create('payment', { invoice_id: inv.id, payment_method_id: pm.id, amount: inv.amount_due, status: 'succeeded', failure_code: null, kind: 'manual' }); ctx.db.update('invoice', inv.id, { status: 'paid', paid_at: now, next_retry_at: null }); ctx.db.create('billing_event', { subscription_id: inv.subscription_id, invoice_id: inv.id, kind: 'payment_succeeded', note: 'manual payment with card ending ' + pm.last4 }); if (sub !== null && sub.status === 'past_due') { ctx.db.update('subscription', sub.id, { status: 'active' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'reactivated', note: 'subscription reactivated after manual payment' }); } return { status: 200, body: paid }; }"
jobs:
  billing_cycle:
    description: "Every hour. Renews active subscriptions whose period has ended: creates the next invoice at the current plan amount, advances the period from the old end, charges the default card (kind renewal) and starts dunning on failure. Past_due and canceled subscriptions are skipped."
    every: 1h
    run: "(ctx) => { const now = ctx.now(); const FAIL = { tok_chargeDeclined: 'card_declined', tok_insufficient_funds: 'insufficient_funds', tok_expired_card: 'expired_card' }; const before = (a, b) => (/^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d\\.\\d{3}Z$/.test(a) && /^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d\\.\\d{3}Z$/.test(b)) ? a > b : ctx.time.minutesBetween(a, b) < 0; let seq = -1; const nextSeq = () => { if (seq < 0) { seq = 0; for (const i of ctx.db.list('invoice')) { const n = parseInt(String(i.number).replace(/[^0-9]/g, ''), 10); if (n > seq) seq = n; } } return seq + 1; }; for (const sub of ctx.db.list('subscription', { where: { status: 'active' } })) { if (before(sub.current_period_end, now)) continue; const plan = ctx.db.get('plan', sub.plan_id); const cus = ctx.db.get('customer', sub.customer_id); const start = sub.current_period_end; const end = ctx.time.plus(start, (plan.interval === 'year' ? 365 : 30) + 'd'); seq = nextSeq(); ctx.db.update('subscription', sub.id, { current_period_start: start, current_period_end: end }); const inv = ctx.db.create('invoice', { number: 'INV-' + String(seq).padStart(4, '0'), subscription_id: sub.id, customer_id: cus.id, amount_due: plan.amount, period_start: start, period_end: end, attempt_count: 1, dunning_started_at: null, next_retry_at: null, last_failure_code: null, paid_at: null }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'renewed', note: 'renewed for ' + start + ' to ' + end + ', invoice ' + inv.number }); let pm = cus.default_payment_method_id ? ctx.db.get('payment_method', cus.default_payment_method_id) : null; if (pm !== null && !pm.active) pm = null; const code = pm === null ? 'no_payment_method' : (FAIL[pm.token] === undefined ? null : FAIL[pm.token]); if (code === null) { ctx.db.create('payment', { invoice_id: inv.id, payment_method_id: pm.id, amount: plan.amount, status: 'succeeded', failure_code: null, kind: 'renewal' }); ctx.db.update('invoice', inv.id, { status: 'paid', paid_at: now }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'payment_succeeded', note: 'renewal paid with card ending ' + pm.last4 }); } else { const next = ctx.time.plus(now, '1d'); ctx.db.create('payment', { invoice_id: inv.id, payment_method_id: pm === null ? null : pm.id, amount: plan.amount, status: 'failed', failure_code: code, kind: 'renewal' }); ctx.db.update('invoice', inv.id, { dunning_started_at: now, next_retry_at: next, last_failure_code: code }); ctx.db.update('subscription', sub.id, { status: 'past_due' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'payment_failed', note: 'renewal charge failed: ' + code }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'past_due', note: 'subscription is past due' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'retry_scheduled', note: 'next retry scheduled for ' + next }); } } }"
  dunning_retry:
    description: Every hour. Retries open invoices of past_due subscriptions at attempt_count 1 to 3 once next_retry_at has passed, charging the customer's current default card (kind retry). Success pays the invoice and reactivates the subscription. Failure schedules the next retry at dunning_started_at + 3d then + 7d. The 4th failed attempt makes the invoice uncollectible and cancels the subscription with reason dunning_exhausted.
    every: 1h
    run: "(ctx) => { const now = ctx.now(); const before = (a, b) => (/^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d\\.\\d{3}Z$/.test(a) && /^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d\\.\\d{3}Z$/.test(b)) ? a > b : ctx.time.minutesBetween(a, b) < 0; const FAIL = { tok_chargeDeclined: 'card_declined', tok_insufficient_funds: 'insufficient_funds', tok_expired_card: 'expired_card' }; for (const inv of ctx.db.list('invoice', { where: { status: 'open' } })) { if (inv.attempt_count < 1 || inv.attempt_count > 3) continue; if (inv.next_retry_at === null || inv.next_retry_at === undefined) continue; if (before(inv.next_retry_at, now)) continue; const sub = ctx.db.get('subscription', inv.subscription_id); if (sub === null || sub.status !== 'past_due') continue; const cus = ctx.db.get('customer', inv.customer_id); let pm = cus.default_payment_method_id ? ctx.db.get('payment_method', cus.default_payment_method_id) : null; if (pm !== null && !pm.active) pm = null; const code = pm === null ? 'no_payment_method' : (FAIL[pm.token] === undefined ? null : FAIL[pm.token]); const n = inv.attempt_count + 1; if (code === null) { ctx.db.create('payment', { invoice_id: inv.id, payment_method_id: pm.id, amount: inv.amount_due, status: 'succeeded', failure_code: null, kind: 'retry' }); ctx.db.update('invoice', inv.id, { status: 'paid', paid_at: now, attempt_count: n, next_retry_at: null }); ctx.db.update('subscription', sub.id, { status: 'active' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'payment_succeeded', note: 'retry ' + (n - 1) + ' succeeded' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'reactivated', note: 'subscription reactivated after retry' }); continue; } ctx.db.create('payment', { invoice_id: inv.id, payment_method_id: pm === null ? null : pm.id, amount: inv.amount_due, status: 'failed', failure_code: code, kind: 'retry' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'payment_failed', note: 'retry ' + (n - 1) + ' failed: ' + code }); if (n >= 4) { ctx.db.update('invoice', inv.id, { status: 'uncollectible', attempt_count: n, next_retry_at: null, last_failure_code: code }); ctx.db.update('subscription', sub.id, { status: 'canceled', canceled_at: now, cancel_reason: 'dunning_exhausted' }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'canceled', note: 'dunning exhausted after the day 7 retry' }); } else { const next = ctx.time.plus(inv.dunning_started_at, n === 2 ? '3d' : '7d'); ctx.db.update('invoice', inv.id, { attempt_count: n, next_retry_at: next, last_failure_code: code }); ctx.db.create('billing_event', { subscription_id: sub.id, invoice_id: inv.id, kind: 'retry_scheduled', note: 'next retry scheduled for ' + next }); } } }"
