  customer: "(ctx) => { const firsts = ['Cedar','Summit','Brightline','Ironwood','Silverleaf','Redwood','Lakeside','Granite','Copperfield','Maple','Pioneer','Evergreen','Riverside','Oakridge','Starling','Kestrel','Meridian','Juniper','Falcon','Atlas']; const seconds = ['Analytics','Logistics','Robotics','Foods']; const two = (i) => i < 39 || i === 62; const first = (i) => { let e = 0; for (let x = 0; x < i; x++) if (two(x)) e++; return 1 + i + e; }; const rows = []; for (let i = 0; i < 70; i++) { let name = firsts[i % 20] + ' ' + seconds[Math.floor(i / 20)]; if (i === 60) name = 'Harbor Dental'; if (i === 61) name = 'Harbor Dentistry'; if (i === 62) name = 'Bluefin Labs'; const at = ctx.time.plus('2025-01-10T09:00:00.000Z', (i * 9) + 'd'); rows.push({ name, email: 'billing@' + name.toLowerCase().replace(/[^a-z0-9]+/g, '') + '.example', default_payment_method_id: 'pm_' + String(first(i)).padStart(4, '0'), created_at: at, updated_at: at }); } return rows; }"
  payment_method: "(ctx) => { const cus = ctx.rows('customer'); const CAN = [3,9,15,21,27,33,45]; const ACT = [0,6,12,18,24,30,36,40,41,46,48,49,1,7,13]; const kindOf = (k) => CAN.includes(k) ? 'c' : ACT.includes(k) ? 'a' : 'p'; const pd = (c) => c >= 20 && c < 70 && kindOf(c - 20) === 'p'; const FT = ['tok_insufficient_funds','tok_expired_card','tok_chargeDeclined']; const L4 = { tok_insufficient_funds: '9995', tok_expired_card: '0069', tok_chargeDeclined: '0002' }; const brands = ['visa','mastercard','amex','discover']; const rows = []; for (let c = 0; c < 70; c++) { const at = ctx.time.plus(cus[c].created_at, '1d'); const tok = pd(c) ? FT[c % 3] : 'tok_visa'; rows.push({ customer_id: cus[c].id, brand: brands[c % 4], last4: tok === 'tok_visa' ? ['4242','1881','0005','3782'][c % 4] : L4[tok], exp_month: tok === 'tok_expired_card' ? 1 : 1 + (c * 5) % 12, exp_year: tok === 'tok_expired_card' ? 2026 : 2027 + c % 5, token: tok, active: true, created_at: at, updated_at: at }); if (c < 39 || c === 62) { const t2 = c === 62 ? 'tok_visa' : (c % 4 === 0 ? 'tok_chargeDeclined' : 'tok_visa'); const at2 = ctx.time.plus(at, '1d'); rows.push({ customer_id: cus[c].id, brand: c === 62 ? 'visa' : brands[(c + 1) % 4], last4: c === 62 ? '4444' : (t2 === 'tok_visa' ? ['1117','5556','8431'][c % 3] : '0002'), exp_month: 1 + (c * 7) % 12, exp_year: 2027 + (c + 2) % 5, token: t2, active: true, created_at: at2, updated_at: at2 }); } } return rows; }"
  subscription: "(ctx) => { const NOW = ctx.now(); const T = ctx.time; const cus = ctx.rows('customer'); const plans = ctx.rows('plan'); const CAN = [3,9,15,21,27,33,45]; const ACT = [0,6,12,18,24,30,36,40,41,46,48,49,1,7,13]; const kindOf = (k) => CAN.includes(k) ? 'c' : ACT.includes(k) ? 'a' : 'p'; const info = (j) => { if (j < 20) return { s: 'active' }; if (j < 70) { const k = j - 20; const t = kindOf(k); if (t === 'c') return { s: 'canceled' }; if (t === 'a') return { s: 'active' }; let p = 0; for (let x = 0; x < k; x++) if (kindOf(x) === 'p') p++; return { s: 'past_due', p }; } return { s: [72,75,78,81,84,87].includes(j) ? 'canceled' : 'active' }; }; const dh = (h) => { const d = Math.floor(h / 24); const r = h % 24; return d === 0 ? r + 'h' : r === 0 ? d + 'd' : d + 'd' + r + 'h'; }; const back = (t, d) => d === 0 ? t : T.minus(t, d + 'd'); const rows = []; for (let j = 0; j < 90; j++) { const c = j < 70 ? j : j - 70; const inf = info(j); let pi; if (j >= 70) pi = 3; else if (inf.s === 'past_due') { const p = inf.p; if (p % 3 === 2) pi = [2,11,17,26].includes(p) ? 2 : (p % 2 === 0 ? 0 : 1); else pi = [0,1,2,1][p % 4]; } else if (j < 20) pi = [0,1,2,0][j % 4]; else if (j === 60 || j === 61) pi = 1; else pi = [0,1,2,1][j % 4]; const plan = plans[pi]; const len = plan.interval === 'year' ? 365 : 30; let row; if (inf.s === 'active') { const end = T.plus(NOW, (1 + (j * 7) % 29) + 'd'); const start = T.minus(end, len + 'd'); const n = len === 365 ? 1 : 1 + j % 2; row = { status: 'active', current_period_start: start, current_period_end: end, canceled_at: null, cancel_reason: null, created_at: back(start, len * (n - 1)), updated_at: start }; } else if (inf.s === 'past_due') { const p = inf.p; const att = p % 3 + 1; const tot = att === 1 ? 1 + (p * 5) % 22 : att === 2 ? 25 + (p * 7) % 45 : 73 + (p * 11) % 90; const ds = T.minus(NOW, dh(tot)); row = { status: 'past_due', current_period_start: ds, current_period_end: T.plus(ds, '30d'), canceled_at: null, cancel_reason: null, created_at: ds, updated_at: att === 1 ? ds : att === 2 ? T.plus(ds, '1d') : T.plus(ds, '3d') }; } else { const reason = j % 2 === 0 ? 'dunning_exhausted' : 'requested'; const ds = T.minus(NOW, (10 + (j * 3) % 60) + 'd'); const ca = T.plus(ds, reason === 'requested' ? '2d' : '7d'); row = { status: 'canceled', current_period_start: ds, current_period_end: T.plus(ds, len + 'd'), canceled_at: ca, cancel_reason: reason, created_at: ds, updated_at: ca }; } rows.push({ customer_id: cus[c].id, plan_id: plan.id, ...row }); } return rows; }"
  invoice: "(ctx) => { const NOW = ctx.now(); const T = ctx.time; const subs = ctx.rows('subscription'); const plans = ctx.rows('plan'); const pms = ctx.rows('payment_method'); const cus = ctx.rows('customer'); const CODE = { tok_insufficient_funds: 'insufficient_funds', tok_expired_card: 'expired_card', tok_chargeDeclined: 'card_declined' }; let n = 0; const rows = []; const mk = (s, plan, o) => { n++; return { number: 'INV-' + String(n).padStart(4, '0'), subscription_id: s.id, customer_id: s.customer_id, amount_due: plan.amount, status: o.status, period_start: o.start, period_end: T.plus(o.start, o.len + 'd'), attempt_count: o.att, dunning_started_at: o.ds || null, next_retry_at: o.next || null, last_failure_code: o.code || null, paid_at: o.paid || null, created_at: o.start, updated_at: o.upd }; }; subs.forEach((s, idx) => { const plan = plans.find((p) => p.id === s.plan_id); const len = plan.interval === 'year' ? 365 : 30; const prior = Math.round(T.minutesBetween(s.created_at, s.current_period_start) / (len * 1440)); for (let m = prior; m >= 1; m--) { const start = T.minus(s.current_period_start, (len * m) + 'd'); rows.push(mk(s, plan, { status: 'paid', start, len, att: 1, paid: start, upd: start })); } const ds = s.current_period_start; if (s.status === 'active') { rows.push(mk(s, plan, { status: 'paid', start: ds, len, att: 1, paid: ds, upd: ds })); } else if (s.status === 'past_due') { const hrs = T.minutesBetween(ds, NOW) / 60; const att = hrs < 24 ? 1 : hrs < 72 ? 2 : 3; const cu = cus.find((c) => c.id === s.customer_id); const pm = pms.find((p) => p.id === cu.default_payment_method_id); rows.push(mk(s, plan, { status: 'open', start: ds, len, att, ds, next: T.plus(ds, ['1d','3d','7d'][att - 1]), code: CODE[pm.token], upd: [ds, T.plus(ds, '1d'), T.plus(ds, '3d')][att - 1] })); } else { const code = ['card_declined','insufficient_funds','expired_card'][idx % 3]; if (s.cancel_reason === 'requested') rows.push(mk(s, plan, { status: 'void', start: ds, len, att: 1, ds, code, upd: s.canceled_at })); else rows.push(mk(s, plan, { status: 'uncollectible', start: ds, len, att: 4, ds, code, upd: s.canceled_at })); } }); return rows; }"
  payment: "(ctx) => { const T = ctx.time; const invs = ctx.rows('invoice'); const pms = ctx.rows('payment_method'); const cus = ctx.rows('customer'); const firstStart = {}; for (const i of invs) { if (firstStart[i.subscription_id] === undefined || i.period_start < firstStart[i.subscription_id]) firstStart[i.subscription_id] = i.period_start; } const offs = ['0d','1d','3d','7d']; const rows = []; for (const inv of invs) { const kind0 = inv.period_start === firstStart[inv.subscription_id] ? 'initial' : 'renewal'; const cu = cus.find((c) => c.id === inv.customer_id); if (inv.status === 'paid') { const card = pms.find((p) => p.customer_id === inv.customer_id); rows.push({ invoice_id: inv.id, payment_method_id: card.id, amount: inv.amount_due, status: 'succeeded', failure_code: null, kind: kind0, created_at: inv.paid_at, updated_at: inv.paid_at }); } else { for (let i = 0; i < inv.attempt_count; i++) { const t = T.plus(inv.dunning_started_at, offs[i]); rows.push({ invoice_id: inv.id, payment_method_id: cu.default_payment_method_id, amount: inv.amount_due, status: 'failed', failure_code: inv.last_failure_code, kind: i === 0 ? kind0 : 'retry', created_at: t, updated_at: t }); } } } return rows; }"
  billing_event: "(ctx) => { const subs = ctx.rows('subscription'); const invs = ctx.rows('invoice'); const pays = ctx.rows('payment'); const out = []; let q = 0; const ev = (t, s, inv, kind, note) => out.push({ t, q: q++, row: { subscription_id: s, invoice_id: inv, kind, note, created_at: t, updated_at: t } }); for (const s of subs) { const list = invs.filter((i) => i.subscription_id === s.id).sort((a, b) => a.period_start < b.period_start ? -1 : 1); list.forEach((inv, idx) => { ev(inv.period_start, s.id, inv.id, idx === 0 ? 'created' : 'renewed', (idx === 0 ? 'subscribed, invoice ' : 'renewed, invoice ') + inv.number); const ps = pays.filter((p) => p.invoice_id === inv.id); ps.forEach((p, i) => { if (p.status === 'succeeded') { ev(p.created_at, s.id, inv.id, 'payment_succeeded', 'invoice ' + inv.number + ' paid'); } else { ev(p.created_at, s.id, inv.id, 'payment_failed', p.kind + ' charge failed: ' + p.failure_code); if (i === 0) ev(p.created_at, s.id, inv.id, 'past_due', 'subscription is past due'); if (inv.status === 'open' || i < ps.length - 1) ev(p.created_at, s.id, inv.id, 'retry_scheduled', 'retry scheduled for invoice ' + inv.number); } }); }); if (s.status === 'canceled') ev(s.canceled_at, s.id, null, 'canceled', s.cancel_reason === 'requested' ? 'canceled on request' : 'dunning exhausted after the day 7 retry'); } out.sort((a, b) => a.t < b.t ? -1 : a.t > b.t ? 1 : a.q - b.q); return out.map((o) => o.row); }"
tests:
  subscribe_success_charges_first_invoice:
    description: A customer with a tok_visa default card subscribes to a 4900 monthly plan. The subscription is active with a 30-day period, the invoice is paid and one succeeded initial payment exists.
    script: |-
      (ctx) => {
        const post = (p, b) => { const r = ctx.api('POST', p, b); ctx.assert(r.status >= 200 && r.status < 300, 'POST ' + p + ' returned ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
        ctx.assert(ctx.now() === '2026-10-06T09:00:00.000Z', 'clock starts at 2026-10-06T09:00:00.000Z, got ' + ctx.now());
        const cus = post('/customers', { name: 'Good Card Co', email: 'ap@goodcardco.example' });
        const plan = post('/plans', { name: 'Pro Test', code: 'pro_test_ok', amount: 4900, interval: 'month' });
        const pm = post('/payment_methods', { customer_id: cus.id, brand: 'visa', last4: '4242', exp_month: 12, exp_year: 2030, token: 'tok_visa' });
        const def = post('/customers/' + cus.id + '/default_payment_method', { payment_method_id: pm.id });
        ctx.assert(def.default_payment_method_id === pm.id, 'default card set, got ' + JSON.stringify(def));
        const r = ctx.api('POST', '/subscriptions', { customer_id: cus.id, plan_id: plan.id });
        ctx.assert(r.status === 201, 'subscribe returned ' + r.status + ' ' + JSON.stringify(r.body));
        const sub = r.body;
        ctx.assert(sub.status === 'active' && sub.customer_id === cus.id && sub.plan_id === plan.id, 'active subscription, got ' + JSON.stringify(sub));
        ctx.assert(sub.current_period_start === '2026-10-06T09:00:00.000Z' && sub.current_period_end === '2026-11-05T09:00:00.000Z', 'period is 30 days from start, got ' + sub.current_period_start + ' to ' + sub.current_period_end);
        const invs = ctx.api('GET', '/subscriptions/' + sub.id + '/invoices').body.data;
        ctx.assert(invs.length === 1, 'one invoice, got ' + invs.length);
        ctx.assert(invs[0].status === 'paid' && invs[0].amount_due === 4900 && invs[0].attempt_count === 1 && invs[0].paid_at === '2026-10-06T09:00:00.000Z' && invs[0].next_retry_at === null, 'invoice paid for 4900, got ' + JSON.stringify(invs[0]));
        const pays = ctx.api('GET', '/invoices/' + invs[0].id + '/payments').body.data;
        ctx.assert(pays.length === 1 && pays[0].status === 'succeeded' && pays[0].kind === 'initial' && pays[0].amount === 4900 && pays[0].payment_method_id === pm.id, 'one succeeded initial payment, got ' + JSON.stringify(pays));
      }
  declined_first_charge_starts_dunning:
    description: A customer whose only card fails with insufficient_funds subscribes. The call still answers 201. The subscription is past_due, the invoice is open with attempt_count 1, next_retry_at one day out and a failed payment on record.
    script: |-
      (ctx) => {
        const post = (p, b) => { const r = ctx.api('POST', p, b); ctx.assert(r.status >= 200 && r.status < 300, 'POST ' + p + ' returned ' + r.status + ' ' + JSON.stringify(r.body)); return r.body; };
        const cus = post('/customers', { name: 'Declined Co', email: 'ap@declinedco.example' });
