  recover_bluefin_labs_with_backup_card:
    difficulty: medium
    instruction: Bluefin Labs' subscription is past due because its default card keeps getting declined. They already have a backup card ending in 4444 on file. Make that card the customer's default payment method, then collect their open invoice now using it. Do not add new cards or cancel anything.
    grader: |-
      (ctx) => {
        const cus = ctx.seed.list('customer', { where: { name: 'Bluefin Labs' } })[0];
        if (!cus) return 0;
        const backup = ctx.seed.list('payment_method', { where: { customer_id: cus.id } }).find((p) => p.last4 === '4444');
        const sub = ctx.seed.list('subscription', { where: { customer_id: cus.id, status: 'past_due' } })[0];
        if (!backup || !sub) return 0;
        const inv = ctx.seed.list('invoice', { where: { subscription_id: sub.id, status: 'open' } })[0];
        if (!inv) return 0;
        const pays = ctx.db.list('payment', { where: { invoice_id: inv.id } }).filter((p) => ctx.seed.get('payment', p.id) === null);
        const events = ctx.db.list('billing_event', { where: { subscription_id: sub.id } }).filter((e) => ctx.seed.get('billing_event', e.id) === null);
        ctx.guardChanges('only the default card, the invoice, the subscription status and their new payments and events changed', [
          { entity: 'customer', id: cus.id, kind: 'updated', fields: ['default_payment_method_id'] },
          { entity: 'invoice', id: inv.id, kind: 'updated', fields: ['status', 'paid_at', 'next_retry_at'] },
          { entity: 'subscription', id: sub.id, kind: 'updated', fields: ['status'] },
          ...pays.map((p) => ({ entity: 'payment', id: p.id, kind: 'created', fields: ['invoice_id', 'payment_method_id', 'amount', 'status', 'failure_code', 'kind'] })),
          ...events.map((e) => ({ entity: 'billing_event', id: e.id, kind: 'created', fields: ['subscription_id', 'invoice_id', 'kind', 'note'] })),
        ]);
        ctx.guard('no failed charge was attempted', pays.every((p) => p.status === 'succeeded'));
        const trace = ctx.trace();
        const firstPay = trace.find((c) => c.routeId === 'pay_invoice');
        const firstSet = trace.find((c) => c.routeId === 'set_default_payment_method');
        ctx.guard('the default card was switched before the invoice was collected', !firstPay || (firstSet !== undefined && firstSet.seq < firstPay.seq));
        const cEnd = ctx.db.get('customer', cus.id);
        const iEnd = ctx.db.get('invoice', inv.id);
        const sEnd = ctx.db.get('subscription', sub.id);
        ctx.guard('manual payment did not change the dunning attempt count', iEnd.attempt_count === inv.attempt_count);
        ctx.goal(0.3, 'the 4444 card is the default', cEnd.default_payment_method_id === backup.id);
        ctx.goal(0.4, 'the invoice is paid by a succeeded payment on the 4444 card', iEnd.status === 'paid' && pays.some((p) => p.status === 'succeeded' && p.payment_method_id === backup.id));
        ctx.goal(0.3, 'the subscription is active again', sEnd.status === 'active');
        return ctx.score();
      }
    solution: |-
      (ctx) => {
        const cus = ctx.api('GET', '/customers?q=Bluefin').body.data.find((c) => c.name === 'Bluefin Labs');
        ctx.assert(cus, 'customer Bluefin Labs not found');
        const cards = ctx.api('GET', '/customers/' + cus.id + '/payment_methods').body.data;
        const backup = cards.find((p) => p.last4 === '4444' && p.active);
        ctx.assert(backup, 'no active card ending 4444');
        const invs = ctx.api('GET', '/invoices?customer_id=' + cus.id + '&status=open').body.data;
        ctx.assert(invs.length === 1, 'expected one open invoice, found ' + invs.length);
