  cancel_final_retry_business_subscriptions:
    difficulty: hard
    instruction: Finance wants to stop dunning for the biggest accounts about to take their last retry. Cancel every subscription on the Business plan that is past due and whose open invoice is on its third charge attempt, so only the 7-day retry is left. Leave every other subscription alone, including other past due ones. Change nothing else.
    grader: |-
      (ctx) => {
        const plan = ctx.seed.list('plan', { where: { code: 'business_monthly' } })[0];
        if (!plan) return 0;
        const openInvoices = (s) => ctx.seed.list('invoice', { where: { subscription_id: s.id, status: 'open' } });
        const targets = ctx.seed.list('subscription', { where: { status: 'past_due', plan_id: plan.id } })
          .filter((s) => openInvoices(s).some((i) => i.attempt_count === 3));
        if (targets.length === 0) return 0;
        const allowed = [];
        for (const s of targets) {
          allowed.push({ entity: 'subscription', id: s.id, kind: 'updated', fields: ['status', 'canceled_at', 'cancel_reason'] });
          for (const i of openInvoices(s)) allowed.push({ entity: 'invoice', id: i.id, kind: 'updated', fields: ['status', 'next_retry_at'] });
          const events = ctx.db.list('billing_event', { where: { subscription_id: s.id } }).filter((e) => ctx.seed.get('billing_event', e.id) === null);
          for (const e of events) allowed.push({ entity: 'billing_event', id: e.id, kind: 'created', fields: ['subscription_id', 'invoice_id', 'kind', 'note'] });
        }
        ctx.guardChanges('only the target subscriptions, their open invoices and their new events changed', allowed);
        let done = 0;
        for (const s of targets) {
          const end = ctx.db.get('subscription', s.id);
          const voided = openInvoices(s).every((i) => ctx.db.get('invoice', i.id).status === 'void');
          if (end.status === 'canceled' && end.cancel_reason === 'requested' && voided) done += 1;
        }
        return done / targets.length;
      }
